import{_ as t,a,c as r,k as o}from"./chunks/framework.CfBWHN5N.js";const m=JSON.parse('{"title":"About Keith Williams","description":"Meet Keith Williams, an NJIT lecturer and Enterprise AI program director whose work connects software engineering, classroom teaching, and public services.","frontmatter":{"title":"About Keith Williams","description":"Meet Keith Williams, an NJIT lecturer and Enterprise AI program director whose work connects software engineering, classroom teaching, and public services.","teaser":"A home computer in Pittsburgh, a classroom in Newark, and software work in Zambia shaped the way I teach people to build with AI."},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),n={name:"about.md"};function i(s,e,h,l,d,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="about-keith-williams" tabindex="-1">About Keith Williams <a class="header-anchor" href="#about-keith-williams" aria-label="Permalink to &quot;About Keith Williams&quot;">​</a></h1><p>I’m a Senior University Lecturer at the New Jersey Institute of Technology and director of its B.S. in Enterprise AI. When a student shows me a working project, I like to hand it to someone else. What happens when that person tries something the student never anticipated? That’s often where the most interesting part of the lesson begins. <a href="/teaching">Inside my classroom</a></p><h2 id="where-it-started" tabindex="-1">Where it started <a class="header-anchor" href="#where-it-started" aria-label="Permalink to &quot;Where it started&quot;">​</a></h2><p>My first home computer was a Tandy TRS-80 Color Computer 2. My father worked as a mainframe systems lead operator at Alcoa. Now I had a machine I could program myself, and I started teaching myself how.</p><p>Later, through AmeriCorps, I taught children about computers at an after-school center in Pittsburgh. I’ve also worked with high schools. I still think about the person sitting down at a computer for the first time, wondering what they’re allowed to try.</p><h2 id="building-things-teaching-people" tabindex="-1">Building things, teaching people <a class="header-anchor" href="#building-things-teaching-people" aria-label="Permalink to &quot;Building things, teaching people&quot;">​</a></h2><p>I started teaching at NJIT as an adjunct. I’ve developed courses and helped shape the Web and Information Systems program. Along the way I built Showedme.net, a web application framework and learning management system, and Wrkbench, an iOS collaboration app.</p><p>Today my students use AI coding assistants. In the classroom exercises I call Studios, I can give the assistant a job and reserve a decision for the student. A learner can ask for help, test a prediction, and see what they would change. <a href="/teaching/when-ai-helps-write-the-code">Try a Studio</a></p><h2 id="learning-beyond-my-own-classroom" tabindex="-1">Learning beyond my own classroom <a class="header-anchor" href="#learning-beyond-my-own-classroom" aria-label="Permalink to &quot;Learning beyond my own classroom&quot;">​</a></h2><p>In Zambia, I taught software engineering and worked with government teams on digital public services, user experience, and prototypes. A prototype gave us something concrete to put in front of the person trying to use a service. We could watch where they got stuck and ask what they had expected to happen. <a href="https://news.njit.edu/inspiring-students-njit-africa" target="_blank" rel="noreferrer">NJIT on teaching in Zambia</a> · <a href="https://news.njit.edu/njit-lecturer-helps-digitize-government-services-zambia" target="_blank" rel="noreferrer">NJIT on digitizing government services</a></p><h2 id="what-im-working-on-now" tabindex="-1">What I’m working on now <a class="header-anchor" href="#what-im-working-on-now" aria-label="Permalink to &quot;What I’m working on now {#what-im-working-on-now}&quot;">​</a></h2><p>Two questions keep coming up in my work with AI. How do we tell what someone learned when AI helped them build? How do we trace a confident answer back to the evidence behind it? My <a href="/research">research agenda</a> describes the studies I’d like to run. The <a href="/knowledge-lab/">Knowledge Lab</a> gives readers a retrieval exercise to try, and my <a href="/#projects">project portfolio</a> links to the software and teaching materials behind the work.</p><p>I also write about ordinary uses of AI. <a href="/life-tracker">Life Tracker</a> is the method I use to follow a task from a conversation to a verified result. A separate proposal, EverydayAI Newark, imagines paid workshops helping fund free community learning and opportunities for students to show their work. It is a proposal, not an operating program.</p><h2 id="lets-compare-notes" tabindex="-1">Let’s compare notes <a class="header-anchor" href="#lets-compare-notes" aria-label="Permalink to &quot;Let’s compare notes {#lets-compare-notes}&quot;">​</a></h2><p>I’d like to hear about an assignment that changed how you teach, or a software project that made you rethink what counts as evidence. <a href="https://www.linkedin.com/in/keithwilliams5/" target="_blank" rel="noreferrer">Connect on LinkedIn</a> · <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">Find me at NJIT</a> · <a href="/#conversation">Start a public conversation</a></p><p><em>Parts of this account first appeared on my <a href="https://eaikw.com/about/" target="_blank" rel="noreferrer">earlier About page</a>.</em></p>',16)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
